    std::vector<long long> a(n);
    for (long long& x : a) std::cin >> x;

    std::vector<long long> ls = half_sums(a, 0, n / 2);
    std::vector<long long> rs = half_sums(a, n / 2, n);
    std::sort(rs.begin(), rs.end());

